solution:
module bcd_adder (
    input wire [3:0] a,
    input wire [3:0] b,
    input wire cin,
    output wire [3:0] sum,
    output wire cout
);
    wire [4:0] t = a + b + cin;
    assign cout = (t > 5'd9);
    assign sum  = cout ? (t - 5'd10) : t[3:0];
endmodule

