module bcd_counter(
    input clk,
    input rst,
    output reg [3:0] q1,
    output reg [3:0] q2
);
    always @(posedge clk) begin
        if (rst) begin
            q1 <= 4'd0;
            q2 <= 4'd0;
        end else if (q1 == 4'd9) begin
            q1 <= 4'd0;
            if (q2 == 4'd9) q2 <= 4'd0;
            else            q2 <= q2 + 4'd1;
        end else begin
            q1 <= q1 + 4'd1;
        end
    end
endmodule

