solution:
module seq_detector_moore_00_11(
    input clk,
    input rst,
    input in,
    output y
);
    localparam S_IDLE  = 3'd0,
               S_LAST0 = 3'd1,
               S_LAST1 = 3'd2,
               S_00    = 3'd3,
               S_11    = 3'd4;
    reg [2:0] state, next;

    always @(posedge clk or posedge rst)
        if (rst) state <= S_IDLE;
        else     state <= next;

    always @(*) begin
        case (state)
            S_IDLE:  next = in ? S_LAST1 : S_LAST0;
            S_LAST0: next = in ? S_LAST1 : S_00;
            S_LAST1: next = in ? S_11    : S_LAST0;
            S_00:    next = in ? S_LAST1 : S_00;
            S_11:    next = in ? S_11    : S_LAST0;
            default: next = S_IDLE;
        endcase
    end

    assign y = (state == S_00) || (state == S_11);
endmodule

