solution:
`timescale 1ns / 1ps

module ALU_8bit (
  input [2:0] operation,
  input [7:0] operand_A,
  input [7:0] operand_B,
  output reg [15:0] result,
  output reg carry_flag,
  output reg zero_flag
);

  parameter [2:0] ADD  = 3'b000,
                  SUB  = 3'b001,
                  MUL  = 3'b010,
                  AND  = 3'b011,
                  OR   = 3'b100,
                  NAND = 3'b101,
                  NOR  = 3'b110,
                  XOR  = 3'b111;

  always @(*) begin
    result = 16'd0;
    carry_flag = 1'b0;
    case (operation)
      ADD:  begin result = operand_A + operand_B; carry_flag = result[8]; end
      SUB:  begin result = operand_A - operand_B; carry_flag = (operand_A < operand_B); end
      MUL:  result = operand_A * operand_B;
      AND:  result = {8'b0, operand_A & operand_B};
      OR:   result = {8'b0, operand_A | operand_B};
      NAND: result = {8'b0, ~(operand_A & operand_B)};
      NOR:  result = {8'b0, ~(operand_A | operand_B)};
      XOR:  result = {8'b0, operand_A ^ operand_B};
      default: result = 16'd0;
    endcase
    zero_flag = (result == 16'd0);
  end
endmodule

