module sync_fifo_16x8 (
    input wire clk,
    input wire rst,
    input wire wr,
    input wire rd,
    input wire [7:0] din,
    output wire [7:0] dout,
    output wire full,
    output wire empty
);
    reg [7:0] mem [0:15];
    reg [4:0] wptr, rptr;
    assign empty = (wptr == rptr);
    assign full = ((wptr[4] != rptr[4]) && (wptr[3:0] == rptr[3:0]));
    always @(posedge clk)
        if (rst) begin wptr <= 5'd0; rptr <= 5'd0; end
        else begin
            if (wr && !full) begin mem[wptr[3:0]] <= din; wptr <= wptr + 5'd1; end
            if (rd && !empty) rptr <= rptr + 5'd1;
        end
    assign dout = mem[rptr[3:0]];
endmodule

