module seq_mealy_101 (
    input wire clk,
    input wire rst,
    input wire in,
    output reg y
);
    localparam S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3;
    reg [2:0] state, next;

    always @(posedge clk or posedge rst)
        if (rst) state <= S0;
        else     state <= next;

    always @(*) begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S1 : S2;
            S2: next = in ? S3 : S0;
            S3: next = in ? S1 : S2;
            default: next = S0;
        endcase
    end

    always @(*) y = (state == S2) && (in == 1'b1);
endmodule

