module seq_mealy_1101 (
    input wire clk,
    input wire rst,
    input wire in,
    output reg y
);
    localparam S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3, S4 = 3'd4;
    reg [2:0] state, next;

    always @(posedge clk or posedge rst)
        if (rst) state <= S0;
        else     state <= next;

    always @(*) begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S2 : S0;
            S2: next = in ? S2 : S3;
            S3: next = in ? S4 : S0;
            S4: next = in ? S2 : S0;
            default: next = S0;
        endcase
    end

    always @(*) y = (state == S3) && (in == 1'b1);
endmodule

